-- Creates the SpecGate Workspace schema on Postgres (Supabase), matching backend/app/ws/models.py column for column.

-- Ids are generated by the backend ("u_", "w_", "ch_"... + 16 hex chars), so text primary keys carry no default.
-- Foreign keys the ORM does not declare are DEFERRABLE INITIALLY DEFERRED: the backend deletes parent and child rows
-- in one flush in any order (task subtrees), and a deferred check only runs at commit.

CREATE TABLE ws_users (
    id                 varchar     PRIMARY KEY,
    display_name       varchar(40) NOT NULL CHECK (btrim(display_name) <> ''),
    created_at         timestamptz NOT NULL DEFAULT now(),
    last_workspace_id  varchar
);

CREATE TABLE ws_oauth_accounts (
    id       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    provider varchar NOT NULL CHECK (provider IN ('google', 'github')),
    subject  varchar NOT NULL,
    login    varchar NOT NULL,
    user_id  varchar NOT NULL REFERENCES ws_users (id),
    CONSTRAINT uq_ws_oauth_accounts_provider_subject UNIQUE (provider, subject)
);
CREATE INDEX idx_ws_oauth_accounts_user_id ON ws_oauth_accounts (user_id);

CREATE TABLE ws_workspaces (
    id           varchar     PRIMARY KEY,
    kind         varchar     NOT NULL CHECK (kind IN ('personal', 'shared')),
    name         varchar(80) NOT NULL,
    brief        text        NOT NULL DEFAULT '',
    visibility   varchar     NOT NULL DEFAULT 'hidden' CHECK (visibility IN ('hidden', 'discoverable')),
    owner_id     varchar     NOT NULL REFERENCES ws_users (id),
    join_code    varchar(7),
    join_code_at timestamptz,
    created_at   timestamptz NOT NULL DEFAULT now(),
    board_seq    integer     NOT NULL DEFAULT 0 CHECK (board_seq >= 0),
    task_seq     integer     NOT NULL DEFAULT 0 CHECK (task_seq >= 0),
    tasks_locked boolean     NOT NULL DEFAULT false,
    CONSTRAINT uq_ws_workspaces_join_code UNIQUE (join_code)
);
CREATE INDEX idx_ws_workspaces_owner_id ON ws_workspaces (owner_id);

ALTER TABLE ws_users
    ADD CONSTRAINT fk_ws_users_last_workspace_id FOREIGN KEY (last_workspace_id)
        REFERENCES ws_workspaces (id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE ws_members (
    id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id   varchar     NOT NULL REFERENCES ws_workspaces (id),
    user_id        varchar     NOT NULL REFERENCES ws_users (id),
    role           varchar     NOT NULL CHECK (role IN ('owner', 'member')),
    team_role      varchar(40),
    nickname       varchar(40),
    needs_nickname boolean     NOT NULL DEFAULT false,
    color          integer     NOT NULL DEFAULT 0 CHECK (color >= 0),
    joined_at      timestamptz NOT NULL DEFAULT now(),
    left_at        timestamptz,
    CONSTRAINT uq_ws_members_workspace_id_user_id UNIQUE (workspace_id, user_id)
);
CREATE INDEX idx_ws_members_workspace_id ON ws_members (workspace_id);
CREATE INDEX idx_ws_members_user_id ON ws_members (user_id);

CREATE TABLE ws_channels (
    id           varchar     PRIMARY KEY,
    workspace_id varchar     NOT NULL REFERENCES ws_workspaces (id),
    name         varchar(40) NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_ws_channels_workspace_id_name UNIQUE (workspace_id, name)
);
CREATE INDEX idx_ws_channels_workspace_id ON ws_channels (workspace_id);

CREATE TABLE ws_channel_reads (
    id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    varchar NOT NULL REFERENCES ws_users (id),
    channel_id varchar NOT NULL REFERENCES ws_channels (id),
    last_seq   integer NOT NULL DEFAULT 0 CHECK (last_seq >= 0),
    CONSTRAINT uq_ws_channel_reads_user_id_channel_id UNIQUE (user_id, channel_id)
);
CREATE INDEX idx_ws_channel_reads_user_id ON ws_channel_reads (user_id);
CREATE INDEX idx_ws_channel_reads_channel_id ON ws_channel_reads (channel_id);

CREATE TABLE ws_join_requests (
    id           varchar     PRIMARY KEY,
    workspace_id varchar     NOT NULL REFERENCES ws_workspaces (id),
    user_id      varchar     NOT NULL REFERENCES ws_users (id),
    via          varchar     NOT NULL CHECK (via IN ('code', 'explore')),
    code         varchar(7),
    message      text        NOT NULL DEFAULT '',
    status       varchar     NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'approved', 'rejected', 'cancelled')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    decided_at   timestamptz,
    decided_by   varchar
        CONSTRAINT fk_ws_join_requests_decided_by REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED
);
CREATE INDEX idx_ws_join_requests_workspace_id ON ws_join_requests (workspace_id);
CREATE INDEX idx_ws_join_requests_user_id ON ws_join_requests (user_id);
-- One open request per person and workspace: the backend reuses the pending row instead of adding another.
CREATE UNIQUE INDEX uq_ws_join_requests_pending ON ws_join_requests (workspace_id, user_id) WHERE status = 'pending';

CREATE TABLE ws_provider_keys (
    user_id   varchar     PRIMARY KEY REFERENCES ws_users (id),
    provider  varchar     NOT NULL CHECK (provider IN ('anthropic', 'openai-compatible')),
    base_url  varchar,
    secret    bytea       NOT NULL,
    key_last4 varchar(4)  NOT NULL,
    model     varchar     NOT NULL,
    models    jsonb       NOT NULL DEFAULT '[]'::jsonb,
    saved_at  timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE ws_conversations (
    id           varchar     PRIMARY KEY,
    owner_id     varchar     NOT NULL REFERENCES ws_users (id),
    title        varchar(80) NOT NULL,
    workspace_id varchar     REFERENCES ws_workspaces (id),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ws_conversations_owner_id ON ws_conversations (owner_id);

CREATE TABLE ws_turns (
    id                   varchar     PRIMARY KEY,
    conversation_id      varchar     NOT NULL REFERENCES ws_conversations (id) ON DELETE CASCADE,
    seq                  integer     NOT NULL,
    role                 varchar     NOT NULL CHECK (role IN ('user', 'assistant')),
    text                 text        NOT NULL,
    model                varchar,
    error                varchar,
    stopped              boolean     NOT NULL DEFAULT false,
    version_group        varchar,
    active               boolean     NOT NULL DEFAULT true,
    context_workspace_id varchar
        CONSTRAINT fk_ws_turns_context_workspace_id REFERENCES ws_workspaces (id) DEFERRABLE INITIALLY DEFERRED,
    at                   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ws_turns_conversation_id ON ws_turns (conversation_id);
CREATE INDEX idx_ws_turns_version_group ON ws_turns (version_group);

CREATE TABLE ws_messages (
    id             varchar     PRIMARY KEY,
    workspace_id   varchar     NOT NULL REFERENCES ws_workspaces (id),
    channel_id     varchar     NOT NULL REFERENCES ws_channels (id),
    seq            integer     NOT NULL,
    sender_kind    varchar     NOT NULL CHECK (sender_kind IN ('human', 'agent', 'system')),
    -- A user id, or the literal "system" for notices; hence no foreign key.
    sender_id      varchar     NOT NULL,
    agent_model    varchar,
    agent_provider varchar,
    text           text        NOT NULL,
    body           jsonb       NOT NULL DEFAULT '[]'::jsonb,
    reply_to_id    varchar
        CONSTRAINT fk_ws_messages_reply_to_id REFERENCES ws_messages (id) DEFERRABLE INITIALLY DEFERRED,
    attachment     jsonb,
    cards          jsonb,
    at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ws_messages_workspace_id ON ws_messages (workspace_id);
CREATE INDEX idx_ws_messages_channel_id ON ws_messages (channel_id);
CREATE INDEX idx_ws_messages_seq ON ws_messages (seq);
CREATE INDEX idx_ws_messages_channel_id_seq ON ws_messages (channel_id, seq);

CREATE TABLE ws_highlights (
    id             varchar     PRIMARY KEY,
    owner_id       varchar     NOT NULL REFERENCES ws_users (id),
    workspace_id   varchar     NOT NULL REFERENCES ws_workspaces (id),
    channel_id     varchar     NOT NULL
        CONSTRAINT fk_ws_highlights_channel_id REFERENCES ws_channels (id) DEFERRABLE INITIALLY DEFERRED,
    message_id     varchar     NOT NULL
        CONSTRAINT fk_ws_highlights_message_id REFERENCES ws_messages (id) DEFERRABLE INITIALLY DEFERRED,
    author_kind    varchar     NOT NULL CHECK (author_kind IN ('human', 'agent')),
    author_user_id varchar     NOT NULL
        CONSTRAINT fk_ws_highlights_author_user_id REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    author_model   varchar,
    text           text        NOT NULL,
    label          varchar     NOT NULL CHECK (label IN ('important', 'review')),
    note           text,
    segments       jsonb,
    source_at      timestamptz,
    at             timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ws_highlights_owner_id ON ws_highlights (owner_id);
CREATE INDEX idx_ws_highlights_workspace_id ON ws_highlights (workspace_id);

CREATE TABLE ws_private_highlights (
    id                    varchar     PRIMARY KEY,
    owner_id              varchar     NOT NULL REFERENCES ws_users (id),
    kind                  varchar     NOT NULL DEFAULT 'passage' CHECK (kind IN ('passage', 'summary', 'digest')),
    -- Kept after the conversation is deleted (conversation_deleted = true), so it cannot reference it.
    conversation_id       varchar,
    conversation_title    varchar(80) NOT NULL DEFAULT '',
    conversation_deleted  boolean     NOT NULL DEFAULT false,
    turn_id               varchar
        CONSTRAINT fk_ws_private_highlights_turn_id REFERENCES ws_turns (id)
            ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
    speaker_kind          varchar     NOT NULL CHECK (speaker_kind IN ('agent', 'human')),
    model                 varchar,
    original_text         text        NOT NULL,
    text                  text        NOT NULL,
    source_text           text,
    context_workspace_ids jsonb,
    color                 varchar     NOT NULL DEFAULT 'yellow'
        CHECK (color IN ('yellow', 'green', 'blue', 'pink', 'purple')),
    note                  text,
    attached_turns        jsonb       NOT NULL DEFAULT '[]'::jsonb,
    sends                 jsonb       NOT NULL DEFAULT '[]'::jsonb,
    workspace_id          varchar
        CONSTRAINT fk_ws_private_highlights_workspace_id REFERENCES ws_workspaces (id) DEFERRABLE INITIALLY DEFERRED,
    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX idx_ws_private_highlights_owner_id ON ws_private_highlights (owner_id);
CREATE INDEX idx_ws_private_highlights_conversation_id ON ws_private_highlights (conversation_id);

CREATE TABLE ws_context_digests (
    id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      varchar     NOT NULL REFERENCES ws_users (id),
    workspace_id varchar     NOT NULL REFERENCES ws_workspaces (id),
    upto_seq     integer     NOT NULL,
    count        integer     NOT NULL DEFAULT 0 CHECK (count >= 0),
    model        varchar,
    text         text        NOT NULL,
    blocks       jsonb,
    at           timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_ws_context_digests_user_id_workspace_id UNIQUE (user_id, workspace_id)
);
CREATE INDEX idx_ws_context_digests_user_id ON ws_context_digests (user_id);
CREATE INDEX idx_ws_context_digests_workspace_id ON ws_context_digests (workspace_id);

CREATE TABLE ws_board_items (
    id                varchar     PRIMARY KEY,
    workspace_id      varchar     NOT NULL REFERENCES ws_workspaces (id),
    number            integer     NOT NULL CHECK (number > 0),
    kind              varchar     NOT NULL CHECK (kind IN ('idea', 'note')),
    body              text        NOT NULL,
    status            varchar     CHECK (status IN ('proposed', 'discussing', 'decided', 'rejected')),
    reason            text,
    created_by_kind   varchar     NOT NULL CHECK (created_by_kind IN ('human', 'agent')),
    created_by_id     varchar     NOT NULL,
    created_by_model  varchar,
    source_channel_id varchar
        CONSTRAINT fk_ws_board_items_source_channel_id REFERENCES ws_channels (id) DEFERRABLE INITIALLY DEFERRED,
    source_message_id varchar
        CONSTRAINT fk_ws_board_items_source_message_id REFERENCES ws_messages (id) DEFERRABLE INITIALLY DEFERRED,
    decided_by        varchar
        CONSTRAINT fk_ws_board_items_decided_by REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    decided_at        timestamptz,
    author_label      varchar,
    parts             jsonb,
    at                timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_ws_board_items_workspace_id_number UNIQUE (workspace_id, number),
    -- Ideas move through the statuses; notes never carry one.
    CONSTRAINT ck_ws_board_items_status_by_kind CHECK ((kind = 'idea') = (status IS NOT NULL))
);
CREATE INDEX idx_ws_board_items_workspace_id ON ws_board_items (workspace_id);

CREATE TABLE ws_tasks (
    id           varchar      PRIMARY KEY,
    workspace_id varchar      NOT NULL REFERENCES ws_workspaces (id),
    number       integer      NOT NULL CHECK (number > 0),
    body         varchar(200) NOT NULL,
    parent_id    varchar
        CONSTRAINT fk_ws_tasks_parent_id REFERENCES ws_tasks (id) DEFERRABLE INITIALLY DEFERRED,
    assignee_id  varchar
        CONSTRAINT fk_ws_tasks_assignee_id REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    status       varchar      NOT NULL DEFAULT 'doing' CHECK (status IN ('doing', 'done')),
    created_by   varchar      NOT NULL
        CONSTRAINT fk_ws_tasks_created_by REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    assigned_by  varchar
        CONSTRAINT fk_ws_tasks_assigned_by REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    created_at   timestamptz  NOT NULL DEFAULT now(),
    done_at      timestamptz,
    CONSTRAINT uq_ws_tasks_workspace_id_number UNIQUE (workspace_id, number),
    CONSTRAINT ck_ws_tasks_not_own_parent CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX idx_ws_tasks_workspace_id ON ws_tasks (workspace_id);
CREATE INDEX idx_ws_tasks_parent_id ON ws_tasks (parent_id);
CREATE INDEX idx_ws_tasks_assignee_id ON ws_tasks (assignee_id);

CREATE TABLE ws_briefs (
    id           varchar     PRIMARY KEY,
    workspace_id varchar     NOT NULL REFERENCES ws_workspaces (id),
    built_by     varchar     NOT NULL
        CONSTRAINT fk_ws_briefs_built_by REFERENCES ws_users (id) DEFERRABLE INITIALLY DEFERRED,
    built_at     timestamptz NOT NULL DEFAULT now(),
    data         jsonb       NOT NULL,
    markdown     text        NOT NULL
);
CREATE INDEX idx_ws_briefs_workspace_id ON ws_briefs (workspace_id);

-- The browser never talks to Supabase: the backend connects as the table owner, which RLS does not restrict.
-- RLS with no policy, plus revoked grants, keeps the public anon key from reading any row through the Data API.
DO $$
DECLARE
    table_name text;
BEGIN
    FOR table_name IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' AND tablename LIKE 'ws\_%' LOOP
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
            EXECUTE format('REVOKE ALL ON public.%I FROM anon, authenticated', table_name);
        END IF;
    END LOOP;
END $$;
